const { useEffect, useState } = React;

function requestProduct(name) {
  const delay = name === '셔츠' ? 1000 : 200;
  return new Promise((resolve) => setTimeout(() => resolve(name + ' 결과'), delay));
}

function Search() {
  const [query, setQuery] = useState('');
  const [result, setResult] = useState('선택하세요');

  useEffect(() => {
    if (query === '') return;
    let ignore = false;

    requestProduct(query).then((nextResult) => {
      if (!ignore) setResult(nextResult);
    });

    return () => { ignore = true; };
  }, [query]);

  return (
    <section>
      <button type="button" onClick={() => setQuery('셔츠')}>셔츠</button>
      <button type="button" onClick={() => setQuery('모자')}>모자</button>
      <p>{result}</p>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Search />);

